package org.example;

public class Alumno {
    private int numero;
    private String nombre;
    private String apellido;
    private int edad;
    private String materiaAprobada;
    private int nota;

    public Alumno(int numero, String nombre, String apellido, int edad, String materiaAprobada, int nota) {
        this.numero = numero;
        this.nombre = nombre;
        this.apellido = apellido;
        this.edad = edad;
        this.materiaAprobada = materiaAprobada;
        this.nota = nota;
    }

    public int getNota() {
        return this.nota;
    }

    public String getMateriaAprobada() {
        return this.materiaAprobada;
    }

    public String getNombre() {
        return this.nombre;
    }

    @Override
    public String toString() {
        return this.nombre + " " + this.apellido + " " + this.materiaAprobada + " " + this.nota;
    }
}
